// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 ticketAmount, uint256 randomValue) public {
        vm.assume(ticketAmount == 10);
        vm.assume(randomValue < 2);
        uint256 potBefore = c.pot();
        uint256 bankBalanceBefore = address(c.bank()).balance;

        // Simulate a play with the given random value by manipulating block.difficulty and block.timestamp
        // But we cannot directly set those. Instead we use the fact that play() doesn't revert for random == 0 or random == 1
        // We will just call play() and then check invariants after the call
        // Since we cannot control the randomness, we use a bound to ensure we can call multiple times
        // Actually we can just call play() once and assert the invariant

        // Fund the contract
        vm.deal(address(this), ticketAmount);
        vm.prank(address(this));
        c.play{value: ticketAmount}();

        uint256 potAfter = c.pot();
        // Rule: pot should never decrease by more than ticketAmount (since pot decreases only when msg.value is subtracted)
        // In the correct version, pot increases by ticketAmount, so potAfter >= potBefore
        // In the buggy version, pot decreases, so potAfter < potBefore
        // We assert that potAfter >= potBefore (always true in reference, false in buggy because underflow causes revert or pot < potBefore)
        // Since the buggy version does pot -= msg.value which could underflow and revert, we need to catch that
        // But the assertion here is about the state after a successful call
        // Actually the buggy version may revert on underflow, so the call might fail
        // Let's assert the invariant for successful calls
        // We'll use a try/catch approach
        // But the instruction says to drive through public surface, so we can just check after the call if it succeeded
        // For simplicity, we assume the call succeeds (no underflow) and assert potAfter >= potBefore
        // However, the reference always satisfies potAfter >= potBefore, while buggy sometimes has potAfter < potBefore (if no underflow) or reverts
        // Since the test must fail on buggy, we need the call to succeed (no underflow) on buggy and then the assertion fails
        // For the buggy version, pot -= 10 could underflow if pot < 10, causing revert
        // To avoid revert, we need pot >= 10 before the call
        // We can add an assume that potBefore >= 10 for calls after the first
        // But we cannot assume this for the first call because potBefore = 0
        // So we make multiple calls, ensuring that after some successful calls pot grows
        // Actually simpler: use vm.assume(potBefore >= 10) to guarantee the call succeeds
        // But potBefore is state, not a parameter
        // Instead, we can use a sequence: first call to increase pot, then subsequent calls
        // For the test to be fuzz over parameters, we can call play() twice: first call to build pot, second call with assumption that pot >= ticketAmount
        // Let's do that:

        // First call to build pot (this might succeed in both versions)
        vm.deal(address(this), ticketAmount);
        vm.prank(address(this));
        c.play{value: ticketAmount}();

        uint256 potAfterFirst = c.pot();
        // Now potAfterFirst could be 0 or 20 depending on randomness
        // We need pot >= ticketAmount for the second call to avoid underflow in buggy
        // We can use vm.assume(potAfterFirst >= ticketAmount) but that's runtime
        // Actually we can just use a bound on the fuzz param to simulate many calls?
        // This is getting complex. Simpler: use a single call and assert potAfter >= potBefore for all successful calls
        // Since the reference always satisfies this, and buggy may revert on underflow (so no state change), the assertion passes for those cases
        // But we need the test to FAIL on buggy, meaning the assertion must be false for some inputs
        // For buggy, if potBefore >= ticketAmount, then pot decreases, so potAfter < potBefore => assertion fails
        // So we need to ensure vm.assume that potBefore >= ticketAmount at the time of the call
        // But potBefore depends on previous calls. We can solve by doing multiple calls in setUp or using vm.deal to give enough ether?
        // Actually we can set up the state so that potBefore is large enough by calling play() once before the property test
        // Let's do that:
    }

    // We need a separate function to set up pot
    function testFuzz_property_with_setup() public {
        // First, make a few plays to increase pot
        for (uint i = 0; i < 5; i++) {
            vm.deal(address(this), 10);
            vm.prank(address(this));
            c.play{value: 10}();
        }

        uint256 potBefore = c.pot();
        vm.assume(potBefore >= 10);

        vm.deal(address(this), 10);
        vm.prank(address(this));
        c.play{value: 10}();

        uint256 potAfter = c.pot();
        // In reference, potAfter >= potBefore
        // In buggy, potAfter < potBefore
        assertTrue(potAfter >= potBefore, "Pot should not decrease");
    }
}

